# Апрув показывает, какую долю заявок рекламодатель подтвердил и оплатил
def calc_approve_rate(approved, leads):
    """Апрув в процентах: подтверждённые лиды, делённые на все лиды."""
    if leads == 0:
        return 0.0
    return approved / leads * 100
